import{_ as t,c as a,o,ae as r}from"./chunks/framework.Cd-3tpCq.js";const g=JSON.parse('{"title":"Categories","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/shop/categories/index.md","filePath":"api/rest-api/shop/categories/index.md"}'),d={name:"api/rest-api/shop/categories/index.md"};function i(s,e,n,c,h,l){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h1><p>The Categories menu exposes the store&#39;s catalog structure — the browsable departments and sub-departments a shopper navigates. Two endpoints read the same data in two shapes: a <strong>flat list</strong> of individual category rows, and a <strong>nested tree</strong> that mirrors the storefront&#39;s navigation.</p><p>Both are public reads. They need the storefront key and no customer token.</p><h2 id="flat-list-or-tree" tabindex="-1">Flat List or Tree <a class="header-anchor" href="#flat-list-or-tree" aria-label="Permalink to &quot;Flat List or Tree&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Flat list</th><th>Tree</th></tr></thead><tbody><tr><td>Path</td><td><code>GET /api/shop/categories</code></td><td><code>GET /api/shop/category-trees</code></td></tr><tr><td>Shape</td><td>One row per category, paginated</td><td>Roots with <code>children</code> nested inline</td></tr><tr><td>Children</td><td>Path references only, e.g. <code>/api/shop/categories/5</code></td><td>Real nested objects, recursively</td></tr><tr><td>Extras</td><td><code>filterableAttributes</code>, <code>minPrice</code> / <code>maxPrice</code>, <code>parent</code>, image URLs</td><td>Slimmer node — none of those</td></tr><tr><td>Use it for</td><td>Category admin screens, price-range facets, paging through every category</td><td>Navigation menus, sidebars, breadcrumbs</td></tr></tbody></table><p>Build a menu from the <strong>tree</strong>. Building one from the flat list means one request per level, because <code>children</code> there are references rather than objects.</p><h2 id="filtering-and-paging" tabindex="-1">Filtering and Paging <a class="header-anchor" href="#filtering-and-paging" aria-label="Permalink to &quot;Filtering and Paging&quot;">​</a></h2><p>The flat list accepts three parameters:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>parent_id</code></td><td>—</td><td>Return only the direct children of that category. <code>parentId</code> is accepted as an alias. Omit it to list every category.</td></tr><tr><td><code>page</code></td><td><code>1</code></td><td>Page number.</td></tr><tr><td><code>per_page</code></td><td><code>10</code></td><td>Rows per page, capped at 50.</td></tr></tbody></table><p>The tree accepts two:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>parentId</code></td><td>—</td><td>Return that category&#39;s children as the top level. Omitted, the response starts at the root categories. An unknown id returns <code>[]</code>.</td></tr><tr><td><code>depth</code></td><td><code>4</code></td><td>How many levels to nest. <code>depth=1</code> returns the top level with empty <code>children</code>; <code>depth=2</code> adds one level below, and so on.</td></tr></tbody></table><p>There is no name search, no status filter, and no sort parameter. Rows always come back ordered by the <code>position</code> the store set, then by id — the same order the storefront renders them in.</p><h2 id="only-active-categories-are-returned" tabindex="-1">Only Active Categories Are Returned <a class="header-anchor" href="#only-active-categories-are-returned" aria-label="Permalink to &quot;Only Active Categories Are Returned&quot;">​</a></h2><p>Both endpoints hard-filter to <code>status = 1</code> at every level. A disabled category never appears, and neither does anything beneath it, even when its parent is active. Sending <code>?status=0</code> does not override this — the parameter is ignored and active categories come back anyway.</p><p>This is a storefront surface, so there is no way to read a draft or hidden category through it.</p><h2 id="localisation" tabindex="-1">Localisation <a class="header-anchor" href="#localisation" aria-label="Permalink to &quot;Localisation&quot;">​</a></h2><p>Category names, slugs, and descriptions live in a <code>translation</code> block, not at the top level of the category object — the row itself carries no <code>name</code>. Send <code>X-Locale</code> to pick the language; the inline <code>translation</code> follows the request locale, and <code>translations</code> lists every stored language for a client that wants to cache them all at once.</p><h2 id="absent-fields-are-omitted-not-null" tabindex="-1">Absent Fields Are Omitted, Not Null <a class="header-anchor" href="#absent-fields-are-omitted-not-null" aria-label="Permalink to &quot;Absent Fields Are Omitted, Not Null&quot;">​</a></h2><p><code>logoPath</code>, <code>logoUrl</code>, and <code>parent</code> are dropped from the payload entirely when they have no value, rather than being returned as <code>null</code>. A root category therefore has <strong>no</strong> <code>parent</code> key at all. Test for key presence, not for a null value.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/categories/get-categories.html">Categories</a></td><td><code>GET /api/shop/categories</code></td><td>Flat, paginated list. Also documents <code>GET /api/shop/categories/{id}</code> for a single category.</td></tr><tr><td><a href="/api/rest-api/shop/categories/get-category-tree.html">Category Tree</a></td><td><code>GET /api/shop/category-trees</code></td><td>Nested tree for navigation.</td></tr></tbody></table><h2 id="where-categories-are-used-elsewhere" tabindex="-1">Where Categories Are Used Elsewhere <a class="header-anchor" href="#where-categories-are-used-elsewhere" aria-label="Permalink to &quot;Where Categories Are Used Elsewhere&quot;">​</a></h2><ul><li><strong>Product listing</strong> — <code>GET /api/shop/products?category_id=N</code> filters the catalog to one category. The id comes from either endpoint here.</li><li><strong>Category-page facets</strong> — each category inlines <code>filterableAttributes</code> with their options, plus <code>minPrice</code> and <code>maxPrice</code>, so a facet sidebar needs no extra call. There is no separate filters endpoint; see <a href="/api/rest-api/shop/categories/get-categories.html#category-attribute-filters">Category Attribute Filters</a> for the field meanings and how to turn a facet into a product-listing parameter.</li><li><strong>Breadcrumbs</strong> — follow <code>parent</code> upwards on the flat row; its absence marks the root.</li></ul><p>All Category endpoints are public reads that require only the storefront key — see <a href="/api/rest-api/authentication.html">Authentication</a>.</p>',24)]))}const u=t(d,[["render",i]]);export{g as __pageData,u as default};
